+  newFolder->SetStringProperty(kEwsIdProperty, newIds[0]);
+
+  rv = NotifyMessageCopyServiceComplete(mSourceFolder, mDestinationFolder,
+                                        NS_OK);
+
   return NS_OK;
 }

